from produire import produire
from format_lecon import paras,table,steps
parts=[
('La {rétrognathie mandibulaire correspond à une mandibule en retrait}. Elle peut réduire l’espace derrière la langue. Son rôle respiratoire doit être évalué avec le sommeil.',paras('Cette description morphologique ne constitue pas à elle seule un syndrome d’apnées. Une personne peut présenter une mandibule en retrait sans obstruction nocturne significative.', 'Le CHUV cite les anomalies craniofaciales et le recul de la langue parmi les causes d’obstruction. D’autres niveaux, notamment nasal et palatin, peuvent être associés.')),
('Le {contexte peut être isolé ou syndromique}. Une anomalie mandibulaire est pertinente même en l’absence d’obésité. Chez l’enfant, l’âge et la croissance changent l’évaluation.',paras('Les syndromes craniofaciaux et la séquence de Pierre Robin nécessitent une prise en charge spécialisée. Le parcours du nourrisson ne se confond pas avec la prescription d’une orthèse chez l’adulte.', 'Aucun classement de fréquence suisse n’est proposé. La présence d’un facteur anatomique doit être reliée aux symptômes et aux examens fonctionnels.')),
('La {position mandibulaire influence l’espace rétrolingual}. Les attaches et la position de la langue participent au calibre pharyngé. Le relâchement pendant le sommeil peut accentuer la fermeture.',paras('Avancer la mandibule peut augmenter l’espace disponible et tendre certains tissus. Ce mécanisme explique l’action recherchée par une orthèse d’avancement mandibulaire.', 'La réponse varie selon l’anatomie, les autres sites d’obstruction et la tolérance. Une apparence favorable ne permet pas de prédire avec certitude la normalisation respiratoire.')),
('Les {alarmes concernent respiration, alimentation et vigilance}. Un nourrisson avec détresse ou difficultés alimentaires doit être évalué rapidement. Chez l’adulte, la somnolence dangereuse impose de sécuriser la conduite.',paras('Une cyanose ou une détresse à l’éveil requiert une prise en charge immédiate. Chez l’enfant, croissance insuffisante et efforts nocturnes importants sont des motifs prioritaires.', 'Ne pas différer le traitement d’apnées sévères en attendant un projet orthodontique ou chirurgical. La sécurité respiratoire peut nécessiter une prise en charge transitoire adaptée.')),
('L’{anamnèse explore respiration et fonction mandibulaire}. Demander ronflement, pauses, étouffements, fatigue et antécédents orthodontiques. Noter douleurs articulaires, dentition et traitements antérieurs.',paras('Rechercher gêne à la mastication, anomalies de déglutition et difficultés avec un appareil de pression positive. Préciser ce que le patient attend d’une éventuelle intervention.', 'Chez l’enfant, recueillir histoire de croissance, alimentation, développement et syndrome connu. Une histoire familiale ou malformative peut orienter l’équipe spécialisée.')),
('L’{examen associe profil, occlusion et voies aériennes}. Le bilan dentaire évalue les possibilités d’appui et la santé parodontale. Examiner aussi nez, amygdales et langue.',paras('Le spécialiste apprécie articulations temporomandibulaires, mobilité et concordance des maxillaires. Des dents peu nombreuses ou une maladie parodontale peuvent limiter le choix d’une orthèse.', 'L’examen craniofacial ne mesure pas les apnées. Il aide à comprendre le mécanisme et à choisir une option après le bilan du sommeil.')),
('L’{approche syndromique distingue morphologie et maladie respiratoire}. Une rétrognathie peut coexister avec une hypertrophie lymphoïde ou une rhinite. Le traitement doit tenir compte de l’ensemble.',table(['Présentation','Enjeu'],[['Mandibule en retrait sans symptôme respiratoire.','Évaluer le retentissement avant toute intervention.'],['Pauses, étouffements et fatigue.','Documenter les apnées.'],['Malformation craniofaciale et difficultés précoces.','Parcours pédiatrique spécialisé.'],['Douleur articulaire ou mauvais état dentaire.','Réévaluer la possibilité d’une orthèse.'] ])),
('Le {diagnostic anatomique est clinique et spécialisé}. Sa responsabilité dans le ronflement ne se déduit pas d’un seul trait du visage. Les événements respiratoires sont documentés séparément.',paras('Une polygraphie ou polysomnographie établit le trouble du sommeil selon le contexte. Le compte rendu anatomique complète cette information pour sélectionner le traitement.', 'Les recommandations suisses demandent un examen complet et une consultation de l’appareil manducateur avant une orthèse. Une gouttière achetée sans bilan ne remplit pas cette démarche.')),
('Les {examens complémentaires répondent au projet thérapeutique}. Le bilan du sommeil précède une décision visant les apnées. Des examens dentaires ou radiologiques peuvent être utiles au spécialiste.',paras('L’imagerie craniofaciale et les analyses orthodontiques se choisissent selon la question clinique. Il n’est pas proposé ici de scanner systématique à tout ronfleur présentant un menton en retrait.', 'Une endoscopie sous sommeil induit peut aider certaines décisions chirurgicales. Elle ne remplace pas la caractérisation du trouble par un enregistrement du sommeil.')),
('L’{algorithme relie anatomie, sévérité et tolérance}. Traiter d’abord le risque respiratoire. Discuter les options avec une équipe du sommeil et de l’appareil manducateur.',steps('Repérer urgence, apnées suspectées et contexte pédiatrique.', 'Documenter le trouble du sommeil et les obstacles associés.', 'Examiner dentition, parodonte, articulations et projet du patient.', 'Choisir pression positive, orthèse ou intervention spécialisée selon indication.', 'Vérifier objectivement l’efficacité et surveiller les effets dentaires ou articulaires.')),
('La {prise en charge suisse peut inclure une orthèse d’avancement mandibulaire}. Son indication ne dépend pas du seul profil facial. Une chirurgie maxillo-faciale reste une option sélectionnée.',paras('Selon la SSSSC, l’orthèse peut être envisagée pour certaines apnées légères ou modérées, ou après échec de pression positive dans une forme sévère. L’évaluation dentaire préalable recherche les contre-indications et informe sur les contraintes.', 'NICE réserve surtout l’alternative aux adultes ne tolérant pas ou refusant la pression positive et ayant une santé dentaire adaptée. Les modalités suisses restent la référence locale.', 'Une chirurgie d’avancement ou une stratégie orthodontique se discute dans une équipe multidisciplinaire. Aucune dose médicamenteuse n’a de rôle pour corriger cette anatomie. Chez l’enfant, ne pas reprendre les indications d’une orthèse adulte sans expertise pédiatrique.')),
('Le {suivi contrôle efficacité et effets sur l’occlusion}. Une orthèse confortable peut être insuffisamment efficace. Douleurs et changements dentaires doivent être recherchés.',paras('La SSSSC demande généralement une polygraphie ou polysomnographie après réglage, idéalement dans les trois mois ; elle prévoit une exception pour une forme légère devenue asymptomatique. Un suivi annuel de l’appareil manducateur reste nécessaire.', 'La recommandation suisse prévoit une réévaluation de l’indication et de l’efficacité au minimum tous les trois ans. Réévaluer plus tôt devant prise de poids, symptômes, douleur ou problème dentaire.')),
('Le {point clé est une sélection fonctionnelle du traitement}. Le recul mandibulaire est un facteur de risque, pas une preuve autonome d’apnées. Le contrôle du résultat complète l’ajustement du dispositif.',paras('Le bilan dentaire et celui du sommeil sont complémentaires. Le patient ne doit pas arrêter un autre traitement efficace sur la seule disparition du ronflement.'))]
quiz=[('La rétrognathie prouve-t-elle des apnées ?','Non.'),('L’obésité est-elle nécessaire au risque anatomique ?','Non.'),('Quel espace peut être réduit ?','L’espace rétrolingual.'),('Une orthèse achetée sans bilan remplace-t-elle l’évaluation spécialisée ?','Non.'),('Le parodonte doit-il être examiné ?','Oui.'),('Une douleur articulaire peut-elle limiter l’usage ?','Oui.'),('Une étude du sommeil reste-t-elle nécessaire si des apnées sont suspectées ?','Oui.'),('Une image du profil mesure-t-elle la gravité respiratoire ?','Non.'),('Faut-il un scanner systématique ?','Non.'),('Peut-on appliquer automatiquement une orthèse adulte au nourrisson ?','Non.'),('La chirurgie est-elle automatique ?','Non.'),('Une orthèse confortable est-elle forcément efficace ?','Non.'),('Quel contrôle est généralement prévu après réglage ?','Un enregistrement respiratoire, avec l’exception suisse précisée pour certaines formes légères asymptomatiques.'),('Les changements d’occlusion doivent-ils être suivis ?','Oui.')]
produire(7,parts,quiz,(1,3,4,6))
